  8	export interface ServiceAccountCredential {
  9	  projectId: string;
 10	  clientEmail: string;
 11	  privateKey: string;
 12	}
 13	
 14	const serviceAccountKeySchema = z.object({
 15	  type: z.literal("service_account"),
 16	  project_id: z.string().min(1),
 17	  client_email: z.string().email(),
 18	  private_key: z.string().min(1),
 19	});
