 21	type CredentialEnv = Partial<
 22	  Record<"FIREBASE_SERVICE_ACCOUNT_JSON" | "GOOGLE_APPLICATION_CREDENTIALS", string>
 23	>;
 24	
 25	/**
 26	 * Loads the Firebase service account once, at boot (CLAUDE.md, Firestore).
 27	 * `FIREBASE_SERVICE_ACCOUNT_JSON` wins — raw JSON, or base64 of it — otherwise
 28	 * `GOOGLE_APPLICATION_CREDENTIALS` names the key file. Returns `null` when
 29	 * neither is set; throws on anything malformed so a bad key fails the boot,
 30	 * not the first Firestore call. Errors name the source, never the key itself.
 31	 */
 32	export function loadCredential(env: CredentialEnv): ServiceAccountCredential | null {
 33	  const inline = env.FIREBASE_SERVICE_ACCOUNT_JSON;
 34	  if (inline) return validate(parseInline(inline), "FIREBASE_SERVICE_ACCOUNT_JSON");
 35	
 36	  const file = env.GOOGLE_APPLICATION_CREDENTIALS;
 37	  if (file) return validate(parseFile(file), "GOOGLE_APPLICATION_CREDENTIALS");
 38	
 39	  return null;
 40	}
 41	
 42	function parseInline(value: string): unknown {
 43	  const decoded = Buffer.from(value, "base64").toString("utf8");
 44	  for (const candidate of [value, decoded]) {
 45	    try {
 46	      return JSON.parse(candidate);
 47	    } catch {
 48	      // Not this encoding; try the next one.
 49	    }
 50	  }
 51	  throw new Error("FIREBASE_SERVICE_ACCOUNT_JSON is neither JSON nor base64-encoded JSON");
 52	}
 53	
 54	function parseFile(file: string): unknown {
 55	  let contents: string;
 56	  try {
 57	    contents = readFileSync(file, "utf8");
 58	  } catch (err) {
 59	    const code = err instanceof Error && "code" in err ? String(err.code) : "unknown";
 60	    throw new Error(`GOOGLE_APPLICATION_CREDENTIALS: cannot read ${file} (${code})`);
 61	  }
 62	  try {
 63	    return JSON.parse(contents);
 64	  } catch {
 65	    throw new Error(`GOOGLE_APPLICATION_CREDENTIALS: ${file} is not valid JSON`);
 66	  }
 67	}
 68	
 69	function validate(raw: unknown, source: string): ServiceAccountCredential {
 70	  const parsed = serviceAccountKeySchema.safeParse(raw);
 71	  if (!parsed.success) {
 72	    // Paths and messages only: zod issues never include the offending value.
 73	    const problems = parsed.error.issues
 74	      .map((issue) => `${issue.path.join(".") || "(root)"}: ${issue.message}`)
 75	      .join("; ");
 76	    throw new Error(`${source} is not a service-account key (${problems})`);
 77	  }
 78	  return {
 79	    projectId: parsed.data.project_id,
 80	    clientEmail: parsed.data.client_email,
 81	    privateKey: parsed.data.private_key,
 82	  };
 83	}
