 34	/** gRPC status for a `create()` on a document that already exists. */
 35	const ALREADY_EXISTS = 6;
 36	
 37	function parse<T>(schema: z.ZodType<T>, snap: { data(): unknown; ref: { path: string } }): T {
 38	  const parsed = schema.safeParse(snap.data());
 39	  if (!parsed.success) {
 40	    throw new Error(`invalid document at ${snap.ref.path}: ${parsed.error.message}`);
 41	  }
 42	  return parsed.data;
 43	}
