 66	  async createRun(run: Run): Promise<void> {
 67	    // A transaction so two racing creates (a double click) cannot both pass
 68	    // the active-run check (D17). The query filters by uid only and checks
 69	    // status in code: a user has few runs, and no composite index is needed.
 70	    await this.root.firestore.runTransaction(async (tx) => {
 71	      const existing = await tx.get(this.runs().where("uid", "==", run.uid));
 72	      const active = existing.docs
 73	        .map((snap) => parse(runSchema, snap))
 74	        .find((candidate) => isRunActive(candidate.status));
 75	      if (active) throw new ActiveRunExistsError(run.uid, active.runId);
 76	      tx.create(this.runs().doc(run.runId), run);
 77	    });
 78	  }
 79	
 80	  async getActiveRun(uid: string): Promise<Run | null> {
 81	    const snap = await this.runs().where("uid", "==", uid).get();
 82	    const active = snap.docs
 83	      .map((doc) => parse(runSchema, doc))
 84	      .find((run) => isRunActive(run.status));
 85	    return active ?? null;
 86	  }
 87	
 88	  async patchRun(runId: string, delta: RunDelta): Promise<void> {
 89	    const update: Record<string, unknown> = { updatedAt: new Date().toISOString() };
 90	    if (delta.status !== undefined) update.status = delta.status;
 91	    if (delta.reason !== undefined) update.reason = delta.reason;
 92	    for (const [key, by] of Object.entries(delta.funnelIncrements ?? {})) {
 93	      if (by !== undefined) update[`funnel.${key}`] = FieldValue.increment(by);
 94	    }
 95	    await this.runs().doc(runId).update(update);
 96	  }
