 17	 * Without one, development falls back to the in-memory twin; production
 18	 * refuses to start rather than silently losing data.
 19	 */
 20	export function createRepo(config: Config, appName?: string): Persistence {
 21	  const credential = loadCredential(config);
 22	  if (credential) {
 23	    const handle = openFirestore(credential, appName);
 24	    return {
 25	      repo: new FirestoreRepo(handle.db, config.FIRESTORE_NAMESPACE),
 26	      kind: "firestore",
 27	      close: handle.close,
 28	    };
 29	  }
 30	  if (config.NODE_ENV === "production") {
 31	    throw new Error(
 32	      "Refusing to start: production needs a Firestore credential " +
 33	        "(GOOGLE_APPLICATION_CREDENTIALS or FIREBASE_SERVICE_ACCOUNT_JSON)",
 34	    );
 35	  }
 36	  return { repo: new InMemoryRepo(), kind: "memory", close: async () => {} };
