 45	export class FirestoreRepo implements Repo {
 46	  private readonly root: DocumentReference;
 47	
 48	  constructor(db: Firestore, namespace: string) {
 49	    this.root = nsDoc(db, namespace);
 50	  }
 51	
 52	  async getUser(uid: string): Promise<UserDoc | null> {
 53	    const snap = await this.users().doc(uid).get();
 54	    return snap.exists ? parse(userDocSchema, snap) : null;
 55	  }
 56	
 57	  async seedUserIfMissing(uid: string, doc: UserDoc): Promise<void> {
 58	    try {
 59	      await this.users().doc(uid).create(doc);
 60	    } catch (err) {
 61	      if (isAlreadyExists(err)) return;
 62	      throw err;
 63	    }
 64	  }
 65	
 66	  async createRun(run: Run): Promise<void> {
 67	    // A transaction so two racing creates (a double click) cannot both pass
 68	    // the active-run check (D17). The query filters by uid only and checks
 69	    // status in code: a user has few runs, and no composite index is needed.
 70	    await this.root.firestore.runTransaction(async (tx) => {
 71	      const existing = await tx.get(this.runs().where("uid", "==", run.uid));
 72	      const active = existing.docs
 73	        .map((snap) => parse(runSchema, snap))
 74	        .find((candidate) => isRunActive(candidate.status));
 75	      if (active) throw new ActiveRunExistsError(run.uid, active.runId);
 76	      tx.create(this.runs().doc(run.runId), run);
 77	    });
 78	  }
 79	
 80	  async getActiveRun(uid: string): Promise<Run | null> {
 81	    const snap = await this.runs().where("uid", "==", uid).get();
 82	    const active = snap.docs
 83	      .map((doc) => parse(runSchema, doc))
 84	      .find((run) => isRunActive(run.status));
 85	    return active ?? null;
 86	  }
 87	
 88	  async patchRun(runId: string, delta: RunDelta): Promise<void> {
 89	    const update: Record<string, unknown> = { updatedAt: new Date().toISOString() };
 90	    if (delta.status !== undefined) update.status = delta.status;
 91	    if (delta.reason !== undefined) update.reason = delta.reason;
 92	    for (const [key, by] of Object.entries(delta.funnelIncrements ?? {})) {
 93	      if (by !== undefined) update[`funnel.${key}`] = FieldValue.increment(by);
 94	    }
 95	    await this.runs().doc(runId).update(update);
 96	  }
 97	
 98	  async putEvaluation(runId: string, evaluation: Evaluation): Promise<void> {
 99	    await this.jobs(runId).doc(evaluation.jobKey).set(evaluation);
100	  }
101	
102	  async patchEvaluation(runId: string, jobKey: string, delta: EvaluationDelta): Promise<void> {
103	    const update: Record<string, unknown> = { updatedAt: new Date().toISOString() };
104	    if (delta.status !== undefined) update.status = delta.status;
105	    if (delta.verdict !== undefined) update.verdict = delta.verdict;
106	    if (delta.score !== undefined) update.score = delta.score;
107	    if (delta.reason !== undefined) update.reason = delta.reason;
108	    await this.jobs(runId).doc(jobKey).update(update);
109	  }
110	
111	  async isSeen(jobKey: string): Promise<boolean> {
112	    return (await this.seen().doc(jobKey).get()).exists;
113	  }
114	
115	  async markSeen(jobKey: string): Promise<void> {
116	    await this.seen().doc(jobKey).set({ seenAt: new Date().toISOString() });
117	  }
118	
119	  watchRun(runId: string, cb: (run: Run) => void): Unsubscribe {
120	    const ref = this.runs().doc(runId);
121	    return ref.onSnapshot(
122	      (snap) => {
123	        if (!snap.exists) return;
124	        const run = runSchema.safeParse(snap.data());
125	        if (run.success) cb(run.data);
126	        else
127	          logger.error("watch_run_invalid_document", { path: ref.path, error: run.error.message });
128	      },
129	      (err) => logger.error("watch_run_failed", { path: ref.path, error: err.message }),
130	    );
131	  }
132	
133	  watchEvaluations(runId: string, cb: (change: EvaluationChange) => void): Unsubscribe {
134	    // Ordered by creation so the initial snapshot replays evaluations in the
135	    // order they were added (Firestore breaks ties by document id).
136	    const query = this.jobs(runId).orderBy("createdAt");
137	    return query.onSnapshot(
138	      (snap) => {
139	        for (const change of snap.docChanges()) {
140	          const evaluation = this.parseEvaluation(change.doc);
141	          if (evaluation) cb({ type: change.type, evaluation });
142	        }
143	      },
144	      (err) => logger.error("watch_evaluations_failed", { runId, error: err.message }),
145	    );
146	  }
147	
148	  private parseEvaluation(doc: QueryDocumentSnapshot): Evaluation | null {
149	    const parsed = evaluationSchema.safeParse(doc.data());
150	    if (parsed.success) return parsed.data;
151	    logger.error("watch_evaluations_invalid_document", {
152	      path: doc.ref.path,
153	      error: parsed.error.message,
154	    });
155	    return null;
156	  }
157	
158	  private users(): CollectionReference {
159	    return this.root.collection("users");
160	  }
161	
162	  private runs(): CollectionReference {
163	    return this.root.collection("runs");
164	  }
165	
166	  private jobs(runId: string): CollectionReference {
167	    return this.runs().doc(runId).collection("jobs");
168	  }
169	
170	  private seen(): CollectionReference {
171	    return this.root.collection("seen");
172	  }
173	}
